<template>
    <div>
        <Head title="Colors" />

        <Card title="Color Classes">
            <p>
                Click a class name to copy it. Bootstrap utilities and Material Dashboard components share
                the theme’s semantic colors. Primary is purple, info is cyan, and warning is orange.
                Foreground and subtle background variants adapt to light and dark appearance.
            </p>
            <label for="color-class-copy">Selected classes</label>
            <input id="color-class-copy" ref="copyInput" class="form-control" :value="selectedClasses" readonly @focus="$event.target.select()" />
            <small class="d-block mt-1" role="status">{{ copyMessage }}</small>
        </Card>

        <Card title="Material Dashboard Palette">
            <p>Use these colors for template buttons, badges, alerts, text, and raised card headers.</p>
            <div class="row gy-3">
                <div v-for="color in materialColors" :key="color" class="sm:col-6 lg:col-4">
                    <section class="palette-example">
                        <h4 class="text-capitalize">{{ color }}</h4>
                        <div class="color-swatch mb-3" :style="{ backgroundColor: `var(--material-${color})`, color: `var(--material-${color}-contrast)` }">
                            {{ color }}
                        </div>
                        <div class="d-flex flex-wrap align-items-center gap-2 mb-3">
                            <span :class="`text-${color}`">Sample text</span>
                            <span class="badge" :class="`badge-${color}`">Badge</span>
                            <button type="button" class="btn btn-sm m-0" :class="`btn-${color}`" @click="copyClasses(`btn btn-${color}`)">Button</button>
                        </div>
                        <div class="alert mb-3" :class="`alert-${color}`">Notification</div>
                        <div class="d-flex flex-wrap gap-1">
                            <button v-for="classes in materialClasses(color)" :key="classes" type="button" class="class-copy" @click="copyClasses(classes)">
                                <code>{{ classes }}</code>
                            </button>
                        </div>
                    </section>
                </div>
            </div>
        </Card>

        <Card title="Raised Card Headers">
            <p>Add the color to the header and use <code>card-header-icon</code> for a raised icon tile.</p>
            <div class="row">
                <div v-for="color in materialColors" :key="color" class="sm:col-6 lg:col-4">
                    <Card :title="color" icon="palette" :card-header-class="`card-header-${color}`">
                        <button type="button" class="class-copy" @click="copyClasses(`card-header-${color} card-header-icon`)">
                            <code>{{ `card-header-${color} card-header-icon` }}</code>
                        </button>
                    </Card>
                </div>
            </div>
        </Card>

        <Card title="Theme Foregrounds and Backgrounds">
            <p>
                <code>fg-*</code> sets text color. <code>bg-*</code> sets a solid background.
                Pair a background with <code>fg-contrast-*</code> for its configured contrasting foreground.
            </p>
            <div class="row gy-3">
                <div v-for="color in bootstrapColors" :key="color" class="sm:col-6 lg:col-4">
                    <section class="palette-example">
                        <h4 class="text-capitalize">{{ color }}</h4>
                        <p :class="`fg-${color}`">Foreground text</p>
                        <button type="button" class="color-swatch border-0 w-100" :class="`bg-${color} fg-contrast-${color}`" @click="copyClasses(`bg-${color} fg-contrast-${color}`)">
                            {{ `bg-${color} fg-contrast-${color}` }}
                        </button>
                        <div class="d-flex flex-wrap gap-1 mt-2">
                            <button v-for="classes in [`fg-${color}`, `bg-subtle-${color}`, `bg-muted-${color}`]" :key="classes" type="button" class="class-copy" @click="copyClasses(classes)">
                                <code>{{ classes }}</code>
                            </button>
                        </div>
                    </section>
                </div>
            </div>
        </Card>

        <Card title="Coordinated Theme Colors">
            <p>
                Combine <code>theme-{color}</code> with <code>theme-contrast</code>, <code>theme-subtle</code>,
                or <code>theme-muted</code> to set the background and foreground together.
                Subtle and muted combinations adapt to the active light or dark appearance.
            </p>
            <div class="row gy-3">
                <div v-for="color in bootstrapColors" :key="color" class="sm:col-6 lg:col-4">
                    <div class="d-grid gap-1">
                        <button v-for="variant in ['contrast', 'subtle', 'muted']" :key="variant" type="button" class="color-swatch border-0 text-start" :class="`theme-${color} theme-${variant}`" @click="copyClasses(`theme-${color} theme-${variant}`)">
                            {{ `theme-${color} theme-${variant}` }}
                        </button>
                    </div>
                </div>
            </div>
        </Card>

        <Card title="Surfaces and Text Hierarchy">
            <p>
                Use surface and foreground tokens for containers and supporting text.
                These follow the current appearance. Material component colors keep their brand hue.
            </p>
            <div class="row gy-3">
                <div v-for="surface in ['body', '1', '2', '3']" :key="surface" class="sm:col-6 lg:col-3">
                    <button type="button" class="color-swatch border w-100 fg-body" :class="`bg-${surface}`" @click="copyClasses(`bg-${surface} fg-body`)">
                        {{ `bg-${surface} fg-body` }}
                    </button>
                </div>
            </div>
            <div class="d-flex flex-wrap gap-3 mt-3">
                <button v-for="foreground in ['body', '1', '2', '3']" :key="foreground" type="button" class="class-copy" :class="`fg-${foreground}`" @click="copyClasses(`fg-${foreground}`)">
                    {{ `fg-${foreground}` }}
                </button>
            </div>
        </Card>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';

export default {
    name: 'ColorsDemo',
    components: { Card, Head },
    layout: { pageTitle: 'Colors' },
    data() {
        return {
            materialColors: ['primary', 'info', 'success', 'warning', 'danger', 'rose'],
            bootstrapColors: ['primary', 'secondary', 'info', 'success', 'warning', 'danger', 'rose', 'accent', 'inverse', 'light', 'dark'],
            selectedClasses: '',
            copyMessage: '',
        };
    },
    methods: {
        materialClasses(color) {
            return [`text-${color}`, `btn btn-${color}`, `badge badge-${color}`, `alert alert-${color}`];
        },
        async copyClasses(classes) {
            this.selectedClasses = classes;
            this.copyMessage = '';
            try {
                await navigator.clipboard.writeText(classes);
                if (this.selectedClasses === classes) {
                    this.copyMessage = `Copied ${classes}`;
                }
            } catch {
                if (this.selectedClasses === classes) {
                    this.copyMessage = 'Press Ctrl+C or Command+C to copy the selected classes.';
                    await this.$nextTick();
                    this.$refs.copyInput.focus();
                }
            }
        },
    },
};
</script>

<style scoped>
.palette-example {
    block-size: 100%;
    padding: 1rem;
    border: 1px solid var(--border-color);
    border-radius: .375rem;
}

.color-swatch {
    display: block;
    min-block-size: 4rem;
    padding: 1rem;
    border-radius: .25rem;
    overflow-wrap: anywhere;
}

.class-copy {
    border: 0;
    padding: .25rem;
    background: transparent;
    color: inherit;
    text-align: start;
    overflow-wrap: anywhere;
}
</style>
